import React from "react";
import { Audio } from "@remotion/media";
import { AbsoluteFill, Sequence, staticFile } from "remotion";
import { ColdOpen } from "./ColdOpen";
import { Reveal } from "./Reveal";
import { T } from "./timeline";

export type Sample15Props = {
  readonly music: boolean;
};

/** Script 0:00-0:15: hook through the reveal. Audio is generated by `npm run audio`. */
export const Sample15: React.FC<Sample15Props> = ({ music }) => {
  return (
    <AbsoluteFill style={{ background: "#121618" }}>
      <Sequence name="Cold open" durationInFrames={T.impact + 12}>
        <ColdOpen />
      </Sequence>
      <Sequence name="Reveal" from={T.bracketFly} durationInFrames={T.end - T.bracketFly}>
        <Reveal />
      </Sequence>
      <Audio name="Score" src={staticFile(music ? "audio/sample15.wav" : "audio/sample15-sfx.wav")} />
    </AbsoluteFill>
  );
};
